def test_datasets_shapes():
    assert datasets.load_AraMetLeaves().shape == (59, 50)
    assert datasets.load_AraMetRoots().shape == (59, 53)
    assert datasets.load_golub_df().shape == (2568, 38)
    assert datasets.load_pvalues().shape == (4289,)
    assert datasets.load_AraMetLeaves().columns[0] == "Col0.1"
    assert datasets.load_AraMetLeaves().columns[49] == "mto1.13"


# --------------------------------------------------------------------------- #
# plotting smoke tests
# --------------------------------------------------------------------------- #
def test_plot_cluster_molecules_runs():
    import matplotlib
    matplotlib.use("Agg")
    golub = datasets.load_golub_df()
    hc = dc.cluster_molecule(golub.iloc[:, 0:27], "pearson", "average")
    g1 = dc.cutree(hc, h=0.4)
    ax = dc.plot_cluster_molecules(golub.iloc[:, 0:27], g1, 1)
    assert ax is not None


def test_write_modules(tmp_path):
    golub = datasets.load_golub_df()
    hc = dc.cluster_molecule(golub.iloc[:, 0:27], "pearson", "average")
    g1 = dc.cutree(hc, h=0.4)
    res = dc.get_eigen_molecule(golub, g1)
    out = tmp_path / "modules.txt"
    dc.write_modules(g1, res, str(out))
    text = out.read_text().splitlines()
    assert text[0].startswith("Molecule number")
    assert len(text) > 1
